namespace MaintenancePRO.ViewModels; public sealed class LoginViewModel:BaseViewModel { public string Email {get;set;}=""; public string Password {get;set;}=""; public Command SignInCommand=>new(async()=>{if(string.IsNullOrWhiteSpace(Email)||string.IsNullOrWhiteSpace(Password)){await Shell.Current.DisplayAlert("Champs requis","Saisis ton adresse e-mail et ton mot de passe.","OK");return;} await Shell.Current.GoToAsync("//home/dashboard");}); public Command ForgotCommand=>new(async()=>await Shell.Current.DisplayAlert("Réinitialisation","La réinitialisation sera reliée au backend.","OK")); }